SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP DATABASE IF EXISTS `restaurant_management`;
CREATE DATABASE `restaurant_management` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `restaurant_management`;

CREATE TABLE `customers` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` VARCHAR(12) NOT NULL,
  `full_name` VARCHAR(120) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `email` VARCHAR(120) DEFAULT NULL,
  `address` VARCHAR(255) DEFAULT NULL,
  `birthday` DATE DEFAULT NULL,
  `loyalty_points` INT NOT NULL DEFAULT 0,
  `total_spent` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `visits` INT NOT NULL DEFAULT 0,
  `notes` VARCHAR(255) DEFAULT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_cust_code` (`code`), UNIQUE KEY `uq_cust_phone` (`phone`),
  CONSTRAINT `ck_points` CHECK (`loyalty_points` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `users` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `username` VARCHAR(50) NOT NULL,
  `password` VARCHAR(255) NOT NULL,
  `full_name` VARCHAR(120) NOT NULL,
  `email` VARCHAR(120) DEFAULT NULL,
  `phone` VARCHAR(20) DEFAULT NULL,
  `role` ENUM('admin','waiter','chef','cashier','customer') NOT NULL,
  `customer_id` INT UNSIGNED DEFAULT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `last_login` DATETIME DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_user_name` (`username`), UNIQUE KEY `uq_user_email` (`email`),
  CONSTRAINT `fk_user_cust` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE `categories` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(60) NOT NULL,
  `station` ENUM('Kitchen','Bar') NOT NULL DEFAULT 'Kitchen',
  `sort_order` INT NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_cat_name` (`name`)
) ENGINE=InnoDB;

CREATE TABLE `menu_items` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `category_id` INT UNSIGNED NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `description` VARCHAR(255) DEFAULT NULL,
  `price` DECIMAL(10,2) NOT NULL,
  `is_veg` TINYINT(1) NOT NULL DEFAULT 0,
  `spice_level` TINYINT NOT NULL DEFAULT 0,
  `prep_minutes` SMALLINT NOT NULL DEFAULT 15,
  `icon` VARCHAR(8) DEFAULT NULL,
  `is_available` TINYINT(1) NOT NULL DEFAULT 1,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_item` (`category_id`,`name`),
  CONSTRAINT `fk_item_cat` FOREIGN KEY (`category_id`) REFERENCES `categories`(`id`),
  CONSTRAINT `ck_item_price` CHECK (`price` > 0)
) ENGINE=InnoDB;

CREATE TABLE `dining_tables` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `table_no` VARCHAR(10) NOT NULL,
  `area` ENUM('Indoor','Outdoor','Rooftop','Private') NOT NULL DEFAULT 'Indoor',
  `seats` TINYINT UNSIGNED NOT NULL,
  `status` ENUM('Available','Occupied','Reserved','Cleaning') NOT NULL DEFAULT 'Available',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_table_no` (`table_no`)
) ENGINE=InnoDB;

CREATE TABLE `suppliers` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(20) DEFAULT NULL,
  `email` VARCHAR(120) DEFAULT NULL,
  `address` VARCHAR(255) DEFAULT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_sup_name` (`name`)
) ENGINE=InnoDB;

CREATE TABLE `ingredients` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(80) NOT NULL,
  `unit` ENUM('kg','l','pcs') NOT NULL DEFAULT 'kg',
  `stock` DECIMAL(12,3) NOT NULL DEFAULT 0,
  `reorder_level` DECIMAL(12,3) NOT NULL DEFAULT 0,
  `cost_per_unit` DECIMAL(10,2) NOT NULL DEFAULT 0,
  `supplier_id` INT UNSIGNED DEFAULT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_ing_name` (`name`),
  CONSTRAINT `fk_ing_sup` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`id`) ON DELETE SET NULL,
  CONSTRAINT `ck_ing_stock` CHECK (`stock` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `recipes` (
  `menu_item_id` INT UNSIGNED NOT NULL,
  `ingredient_id` INT UNSIGNED NOT NULL,
  `qty` DECIMAL(10,3) NOT NULL,
  PRIMARY KEY (`menu_item_id`,`ingredient_id`),
  CONSTRAINT `fk_rec_item` FOREIGN KEY (`menu_item_id`) REFERENCES `menu_items`(`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_rec_ing` FOREIGN KEY (`ingredient_id`) REFERENCES `ingredients`(`id`),
  CONSTRAINT `ck_rec_qty` CHECK (`qty` > 0)
) ENGINE=InnoDB;

CREATE TABLE `stock_movements` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `ingredient_id` INT UNSIGNED NOT NULL,
  `type` ENUM('Purchase','Usage','Wastage','Adjustment') NOT NULL,
  `qty` DECIMAL(12,3) NOT NULL,
  `unit_cost` DECIMAL(10,2) DEFAULT NULL,
  `reference` VARCHAR(80) DEFAULT NULL,
  `supplier_id` INT UNSIGNED DEFAULT NULL,
  `created_by` INT UNSIGNED DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), KEY `ix_mov_ing` (`ingredient_id`,`created_at`),
  CONSTRAINT `fk_mov_ing` FOREIGN KEY (`ingredient_id`) REFERENCES `ingredients`(`id`)
) ENGINE=InnoDB;

CREATE TABLE `reservations` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `res_no` VARCHAR(14) NOT NULL,
  `customer_id` INT UNSIGNED DEFAULT NULL,
  `guest_name` VARCHAR(120) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `party_size` TINYINT UNSIGNED NOT NULL,
  `res_date` DATE NOT NULL,
  `res_time` TIME NOT NULL,
  `table_id` INT UNSIGNED DEFAULT NULL,
  `status` ENUM('Booked','Seated','Completed','Cancelled','No-show') NOT NULL DEFAULT 'Booked',
  `source` ENUM('Staff','Online') NOT NULL DEFAULT 'Staff',
  `notes` VARCHAR(255) DEFAULT NULL,
  `created_by` INT UNSIGNED DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_res_no` (`res_no`), KEY `ix_res_when` (`res_date`,`res_time`),
  CONSTRAINT `fk_res_cust` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_res_table` FOREIGN KEY (`table_id`) REFERENCES `dining_tables`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE `orders` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_no` VARCHAR(14) NOT NULL,
  `type` ENUM('Dine-in','Takeaway','Delivery') NOT NULL DEFAULT 'Dine-in',
  `source` ENUM('Staff','Online') NOT NULL DEFAULT 'Staff',
  `table_id` INT UNSIGNED DEFAULT NULL,
  `customer_id` INT UNSIGNED DEFAULT NULL,
  `reservation_id` INT UNSIGNED DEFAULT NULL,
  `waiter_id` INT UNSIGNED DEFAULT NULL,
  `guest_name` VARCHAR(120) DEFAULT NULL,
  `guest_phone` VARCHAR(20) DEFAULT NULL,
  `guests` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `delivery_address` VARCHAR(255) DEFAULT NULL,
  `note` VARCHAR(255) DEFAULT NULL,
  `status` ENUM('Open','Billed','Paid','Cancelled') NOT NULL DEFAULT 'Open',
  `kot_count` SMALLINT NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `closed_at` DATETIME DEFAULT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_order_no` (`order_no`), KEY `ix_order_status` (`status`), KEY `ix_order_created` (`created_at`),
  CONSTRAINT `fk_ord_table` FOREIGN KEY (`table_id`) REFERENCES `dining_tables`(`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ord_cust` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ord_res` FOREIGN KEY (`reservation_id`) REFERENCES `reservations`(`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ord_waiter` FOREIGN KEY (`waiter_id`) REFERENCES `users`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE `order_items` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_id` INT UNSIGNED NOT NULL,
  `menu_item_id` INT UNSIGNED NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `unit_price` DECIMAL(10,2) NOT NULL,
  `qty` SMALLINT UNSIGNED NOT NULL,
  `note` VARCHAR(120) DEFAULT NULL,
  `status` ENUM('Draft','New','Preparing','Ready','Served','Cancelled') NOT NULL DEFAULT 'Draft',
  `station` ENUM('Kitchen','Bar') NOT NULL DEFAULT 'Kitchen',
  `kot_no` SMALLINT DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `sent_at` DATETIME DEFAULT NULL,
  `started_at` DATETIME DEFAULT NULL,
  `ready_at` DATETIME DEFAULT NULL,
  `served_at` DATETIME DEFAULT NULL,
  PRIMARY KEY (`id`), KEY `ix_oi_order` (`order_id`), KEY `ix_oi_status` (`status`),
  CONSTRAINT `fk_oi_order` FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_oi_item` FOREIGN KEY (`menu_item_id`) REFERENCES `menu_items`(`id`),
  CONSTRAINT `ck_oi_qty` CHECK (`qty` > 0)
) ENGINE=InnoDB;

CREATE TABLE `bills` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `bill_no` VARCHAR(14) NOT NULL,
  `order_id` INT UNSIGNED NOT NULL,
  `subtotal` DECIMAL(12,2) NOT NULL,
  `discount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `points_used` INT NOT NULL DEFAULT 0,
  `service_charge` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `tax` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `total` DECIMAL(12,2) NOT NULL,
  `paid` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `status` ENUM('Unpaid','Partial','Paid') NOT NULL DEFAULT 'Unpaid',
  `created_by` INT UNSIGNED DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_bill_no` (`bill_no`), UNIQUE KEY `uq_bill_order` (`order_id`),
  CONSTRAINT `fk_bill_order` FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`),
  CONSTRAINT `ck_bill_paid` CHECK (`paid` >= 0 AND `paid` <= `total`)
) ENGINE=InnoDB;

CREATE TABLE `payments` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `bill_id` INT UNSIGNED NOT NULL,
  `amount` DECIMAL(12,2) NOT NULL,
  `method` ENUM('Cash','Card','Online') NOT NULL,
  `reference` VARCHAR(60) DEFAULT NULL,
  `received_by` INT UNSIGNED DEFAULT NULL,
  `paid_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), KEY `ix_pay_time` (`paid_at`),
  CONSTRAINT `fk_pay_bill` FOREIGN KEY (`bill_id`) REFERENCES `bills`(`id`),
  CONSTRAINT `ck_pay_amt` CHECK (`amount` > 0)
) ENGINE=InnoDB;

CREATE TABLE `audit_log` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` INT UNSIGNED DEFAULT NULL,
  `action` VARCHAR(40) NOT NULL,
  `entity` VARCHAR(40) NOT NULL,
  `entity_id` INT UNSIGNED DEFAULT NULL,
  `details` VARCHAR(255) DEFAULT NULL,
  `ip` VARCHAR(45) DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), KEY `ix_audit_time` (`created_at`)
) ENGINE=InnoDB;
















SET FOREIGN_KEY_CHECKS = 1;
